  GOTCHA_BINDING_MACRO(MPI_File_get_info, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_set_view, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_get_view, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_read_at, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_read_at_all, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_write_at, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_write_at_all, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_iread_at, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_iwrite_at, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_iread_at_all, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_iwrite_at_all, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_read, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_read_all, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_write, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_write_all, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_iread, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_iwrite, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_iread_all, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_iwrite_all, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_seek, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_get_position, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_get_byte_offset, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_read_shared, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_write_shared, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_iread_shared, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_iwrite_shared, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_read_ordered, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_write_ordered, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_seek_shared, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_get_position_shared, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_read_at_all_begin, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_read_at_all_end, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_write_at_all_begin, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_write_at_all_end, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_read_all_begin, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_read_all_end, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_write_all_begin, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_write_all_end, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_read_ordered_begin, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_read_ordered_end, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_write_ordered_begin, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_write_ordered_end, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_get_type_extent, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_set_atomicity, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_get_atomicity, brahma::MPIIO);

  GOTCHA_BINDING_MACRO(MPI_File_sync, brahma::MPIIO);

  num_bindings = bindings.size();
  if (num_bindings > 0) {
    sprintf(tool_name, "%s_mpiio", name);
    gotcha_binding_t* raw_bindings = bindings.data();
    gotcha_wrap(raw_bindings, num_bindings, tool_name);
    bind_priority = priority;
    gotcha_set_priority(tool_name, priority);
  }
  return num_bindings;
